// Structured logging sketch (no frameworks; same shape as pino/winston JSON)
import { randomUUID } from "node:crypto"

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40, fatal: 50 }
const MIN_LEVEL = process.env.LOG_LEVEL || "info"

function log(level, msg, fields = {}) {
  if (LEVELS[level] < LEVELS[MIN_LEVEL]) return
  process.stdout.write(
    JSON.stringify({ ts: new Date().toISOString(), level, msg, ...fields }) + "\n"
  )
}

// request middleware: one requestId ties every line + the response header
function withRequest(req, handler) {
  const requestId = req.headers["x-request-id"] || "req-" + randomUUID().slice(0, 8)
  req.requestId = requestId
  const started = Date.now()
  try {
    const res = handler(req)
    log("info", "request ok", {
      requestId,
      route: req.route,
      status: res.status,
      durationMs: Date.now() - started
    })
    return res
  } catch (err) {
    log("error", "request failed", {
      requestId,
      route: req.route,
      err: err.code || err.name,   // bounded, queryable
      durationMs: Date.now() - started
    })
    throw err
  }
}

withRequest(
  { route: "POST /checkout", headers: {} , handler: () => ({ status: 200 }) },
  () => ({ status: 200 })
)

